function o(e){const t=new Date(e),n=t.getFullYear(),a=String(t.getMonth()+1).padStart(2,"0"),s=String(t.getDate()).padStart(2,"0"),r=String(t.getHours()).padStart(2,"0"),c=String(t.getMinutes()).padStart(2,"0"),g=String(t.getSeconds()).padStart(2,"0");return`${n}-${a}-${s} ${r}:${c}:${g}`}function i(e){return{pending:"待接单",processing:"制作中",completed:"已完成",cancelled:"已取消"}[e]||e}function p(e){return{pending:"el-tag--warning",processing:"el-tag--primary",completed:"el-tag--success",cancelled:"el-tag--danger"}[e]||""}export{p as a,o as f,i as g};
